sys_script_client.script:
function onSubmit() {

	//g_scratchpad armazena o status da validação. Isso impede que o return seja acionado antes do GlideAjax retornar com a informação
	if(g_scratchpad.isFormValid){
		return true;
	}

	//pegando o botão de submit do formulário
	var actionName = g_form.getActionName();

    var course = g_form.getValue('course');
    var date = g_form.getValue('training_date').split("/");
    date = date[2] + "-" + date[1] + "-" + date[0];

    var gaSchedule = new GlideAjax('ScheduleValidation');
    gaSchedule.addParam('sysparm_name', 'checkDuplicate');
    gaSchedule.addParam('sysparm_course', course.toString());
    gaSchedule.addParam('sysparm_date', date.toString());

    gaSchedule.getXMLAnswer(function(answer) {
        if (answer === 'false') {
			alert('There is already a training for this course on this date');
			g_form.setValue("course", "");
			g_form.setValue("training_date", "");
			g_scratchpad.isFormValid = false;
        } else {
			g_form.clearMessages();
			g_scratchpad.isFormValid = true;
			g_form.submit(actionName);
		}
    });
	return false;
}
